(()=>{"use strict";const cfg=window.MUNDO_DIGITAL_CONFIG||window.MD20_CONFIG||window.CONFIGURACION||{};const $=s=>document.querySelector(s);const state={items:[],actual:null};const E={lista:$('#lista'),cargando:$('#cargando'),vacio:$('#vacio'),total:$('#total'),monto:$('#monto'),hora:$('#hora'),actualizar:$('#actualizar'),modal:$('#modal'),cerrar:$('#cerrar'),titulo:$('#modalTitulo'),detalle:$('#detalle'),comprobante:$('#abrirComprobante'),motivo:$('#motivo'),confirmar:$('#confirmar'),rechazar:$('#rechazar'),mensaje:$('#mensaje')};function api(){return cfg.APPS_SCRIPT_URL||cfg.URL_APPS_SCRIPT||''}function key(){return cfg.API_KEY_SOCIOS||cfg.API_KEY||cfg.CLAVE_API||''}function validarConfiguracion(){const url=String(api()||'').trim();if(!/^https:\/\/script\.google\.com\/macros\/s\/.+\/exec$/i.test(url)){throw new Error('La URL de Apps Script no está configurada correctamente en js/configuracion.js.');}if(!String(key()||'').trim()){throw new Error('Falta API_KEY_SOCIOS en js/configuracion.js.');}}async function get(action){validarConfiguracion();const u=new URL(api());u.searchParams.set('action',action);u.searchParams.set('claveApi',key());const r=await fetch(u);const d=await r.json();if(!d.ok)throw new Error(d.mensaje||'Error');return d}async function post(action,registro){validarConfiguracion();const r=await fetch(api(),{method:'POST',headers:{'Content-Type':'text/plain;charset=utf-8'},body:JSON.stringify({action,claveApi:key(),registro})});const d=await r.json();if(!d.ok)throw new Error(d.mensaje||'Error');return d}const money=(n,m)=>new Intl.NumberFormat('es-ES',{minimumFractionDigits:2,maximumFractionDigits:2}).format(Number(n||0))+' '+(m||'USD');function msg(t){E.mensaje.textContent=t;E.mensaje.classList.add('visible');setTimeout(()=>E.mensaje.classList.remove('visible'),3500)}function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}async function cargar(){E.cargando.hidden=false;E.vacio.hidden=true;E.lista.innerHTML='';try{const d=await get('listarAlertasPagosTiendaMD20');state.items=d.registros||[];render()}catch(e){msg(e.message)}finally{E.cargando.hidden=true}}function render(){E.total.textContent=state.items.length;E.monto.textContent=money(state.items.reduce((s,x)=>s+Number(x.monto||0),0),state.items[0]?.moneda||'USD');E.hora.textContent=new Date().toLocaleTimeString('es-ES',{hour:'2-digit',minute:'2-digit'});E.vacio.hidden=state.items.length>0;E.lista.innerHTML=state.items.map(x=>`<article class="tarjeta"><div><small>${esc(x.numeroPedido||x.numeroVenta)}</small><h3>${esc(x.clienteNombre)} · ${esc(x.productoNombre)}</h3><div class="meta"><span>${esc(x.metodoPagoNombre)}</span><span>Ref. ${esc(x.referencia)}</span><span>${esc(x.bancoOrigen)}</span><span>${esc(x.fechaPago)}</span></div></div><div class="precio"><strong>${money(x.monto,x.moneda)}</strong>${x.totalBs?`<small>${money(x.totalBs,'Bs')}</small>`:''}<button data-id="${esc(x.pagoId)}">Revisar comprobante</button></div></article>`).join('');E.lista.querySelectorAll('[data-id]').forEach(b=>b.onclick=()=>abrir(b.dataset.id))}function abrir(id){const x=state.items.find(i=>i.pagoId===id);if(!x)return;state.actual=x;E.titulo.textContent=x.numeroPedido||x.numeroVenta;E.detalle.innerHTML=`<div><small>Cliente</small><strong>${esc(x.clienteNombre)}</strong></div><div><small>WhatsApp</small><strong>${esc(x.clienteTelefono)}</strong></div><div><small>Producto</small><strong>${esc(x.productoNombre)}</strong></div><div><small>Monto</small><strong>${money(x.monto,x.moneda)}</strong></div><div><small>Método</small><strong>${esc(x.metodoPagoNombre)}</strong></div><div><small>Referencia</small><strong>${esc(x.referencia)}</strong></div><div><small>Banco origen</small><strong>${esc(x.bancoOrigen)}</strong></div><div><small>Titular</small><strong>${esc(x.titular)}</strong></div>`;E.comprobante.href=x.comprobanteUrl||'#';E.comprobante.style.pointerEvents=x.comprobanteUrl?'auto':'none';E.motivo.value='';E.modal.hidden=false}function cerrar(){E.modal.hidden=true;state.actual=null}async function resolver(decision){if(!state.actual)return;const motivo=E.motivo.value.trim();if(decision==='RECHAZAR'&&motivo.length<4){msg('Escribe el motivo del rechazo.');return}E.confirmar.disabled=E.rechazar.disabled=true;try{const d=await post('resolverAlertaPagoTiendaMD20',{pagoId:state.actual.pagoId,decision,motivo,administrador:'ADMINISTRADOR'});msg(d.mensaje);cerrar();await cargar()}catch(e){msg(e.message)}finally{E.confirmar.disabled=E.rechazar.disabled=false}}E.actualizar.onclick=cargar;E.cerrar.onclick=cerrar;E.modal.onclick=e=>{if(e.target===E.modal)cerrar()};E.confirmar.onclick=()=>resolver('CONFIRMAR');E.rechazar.onclick=()=>resolver('RECHAZAR');cargar()})();